-- GENERATED by scripts/social-check-sql.ts from src/lib/social/api.ts. Do not edit by hand:
-- change api.ts, run `npm run social:check-sql`.
--
-- Does this Supabase project have what the website's multiplayer needs? Paste all of this into the SQL
-- editor and Run. It only reads the catalogue; it changes nothing. Every row says ok or MISSING.
--
--   migration   an app migration (Supabase/migrations/NNNN in the app repo) the website leans on
--   rpc         a function the website calls, with exactly those argument names, callable when signed in
--               and NOT by a signed-out visitor (the browser key is public, so this matters)
--   table       a table the website reads: row-level security on, signed-in students may select,
--               a signed-out visitor may not
--   columns     how far up the website's column ladder this server goes (1 = the newest; the website
--               still works from any rung, but newer features need the first)
--   realtime    private-channel policies on realtime.messages (the hall's steps and the chat's pings)
--
-- Anything MISSING under "migration" is a file to run in the SQL editor, in number order, from the app
-- repo's Supabase/migrations. Also turn OFF Realtime > Settings > "Allow public access" (a dashboard
-- setting, so this cannot check it): a channel can then only be joined through the policies above.

WITH
migrations(m, what, ok) AS (VALUES
    ('0104', 'friends and groups (social_profile, friendship, study_group, group_member, study_presence, social_summary)', (to_regclass('public.social_profile') IS NOT NULL AND to_regclass('public.friendship') IS NOT NULL AND to_regclass('public.study_group') IS NOT NULL AND to_regclass('public.group_member') IS NOT NULL AND to_regclass('public.study_presence') IS NOT NULL AND to_regclass('public.social_summary') IS NOT NULL)),
    ('0105', 'anonymous users are refused by every social call (social_caller)', (EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = 'ai_usage_today'))),
    ('0107', 'study hall: emblems, goals, reactions', (EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='study_group' AND column_name='hall_theme') AND to_regclass('public.group_reaction') IS NOT NULL)),
    ('0108', 'avatars (social_profile.avatar, set_avatar)', (EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='social_profile' AND column_name='avatar'))),
    ('0109', 'group chat with moderation (group_message, chat_refusal)', (to_regclass('public.group_message') IS NOT NULL AND to_regclass('public.chat_banned_term') IS NOT NULL)),
    ('0110', 'hall positions (hall_position)', (to_regclass('public.hall_position') IS NOT NULL)),
    ('0112', 'friends'' streaks (social_summary.streak)', (EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='social_summary' AND column_name='streak'))),
    ('0113', 'the hall and chat in real time (private channel policies)', (to_regclass('realtime.messages') IS NOT NULL AND EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='realtime' AND tablename='messages' AND policyname='plumi_realtime_receive') AND EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='realtime' AND tablename='messages' AND policyname='plumi_realtime_send'))),
    ('0117', 'the public lobby (lobby_profile, lobby_presence, lobby_people)', (to_regclass('public.lobby_presence') IS NOT NULL AND to_regclass('public.lobby_profile') IS NOT NULL)),
    ('0119', 'the library chat (library_message)', (to_regclass('public.library_message') IS NOT NULL)),
    ('0120', 'the library chat''s spam rule and Pro tag (library_spam)', (EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = 'library_spam'))),
    ('0121', 'library servers (lobby_servers, a shard of 60)', (EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = 'lobby_servers'))),
    ('0122', 'the ceiling of 300 libraries (lobby_max_shard)', (EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = 'lobby_max_shard'))),
    ('0123', 'library spam rule for every script (a sentence in Chinese or Arabic is not spam)', (EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = 'library_spam' AND p.prosrc LIKE '%uFE00%'))),
    ('0118', 'public groups and asking to join one (request_to_join)', (EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = 'request_to_join')))
),
want_rpc(key, fn, args) AS (VALUES
    ('optIn', 'social_opt_in', ARRAY['colour', 'display_name']::text[]),
    ('optOut', 'social_opt_out', ARRAY[]::text[]),
    ('sendFriendRequest', 'send_friend_request', ARRAY['code']::text[]),
    ('respondFriendRequest', 'respond_friend_request', ARRAY['accept', 'from_user']::text[]),
    ('removeFriend', 'remove_friend', ARRAY['user']::text[]),
    ('block', 'block_user', ARRAY['user']::text[]),
    ('unblock', 'unblock_user', ARRAY['user']::text[]),
    ('reportUser', 'report_user', ARRAY['group', 'reason', 'user']::text[]),
    ('createGroup', 'create_group', ARRAY['name']::text[]),
    ('joinGroup', 'join_group', ARRAY['code']::text[]),
    ('leaveGroup', 'leave_group', ARRAY['group']::text[]),
    ('removeMember', 'remove_member', ARRAY['group', 'user']::text[]),
    ('rotateGroupCode', 'rotate_group_code', ARRAY['group']::text[]),
    ('renameGroup', 'rename_group', ARRAY['group', 'name']::text[]),
    ('setPresence', 'set_presence', ARRAY['ends_at', 'mode', 'phase', 'started_at', 'subject']::text[]),
    ('clearPresence', 'clear_presence', ARRAY[]::text[]),
    ('publishSummaryWeek', 'publish_summary_week', ARRAY['level', 'today_seconds', 'week_seconds', 'week_xp']::text[]),
    ('publishStreak', 'publish_streak', ARRAY['days']::text[]),
    ('setGroupHall', 'set_group_hall', ARRAY['emblem', 'group', 'hall_theme', 'weekly_goal_hours']::text[]),
    ('setGroupVisibility', 'set_group_visibility', ARRAY['group', 'visibility']::text[]),
    ('sendReaction', 'send_reaction', ARRAY['group', 'kind', 'user']::text[]),
    ('markReactionsSeen', 'mark_reactions_seen', ARRAY[]::text[]),
    ('setAvatar', 'set_avatar', ARRAY['avatar']::text[]),
    ('sendGroupMessage', 'send_group_message', ARRAY['body', 'group']::text[]),
    ('reportGroupMessage', 'report_group_message', ARRAY['block', 'message', 'reason']::text[]),
    ('setHallPosition', 'set_hall_position', ARRAY['hall', 'x', 'y']::text[]),
    ('clearHallPosition', 'clear_hall_position', ARRAY[]::text[]),
    ('hallPositions', 'hall_positions', ARRAY['hall']::text[]),
    ('lobbyMe', 'lobby_me', ARRAY[]::text[]),
    ('setLobbyVisible', 'set_lobby_visible', ARRAY['visible']::text[]),
    ('regenerateNickname', 'regenerate_nickname', ARRAY[]::text[]),
    ('lobbyJoin', 'lobby_join', ARRAY['want', 'x', 'y']::text[]),
    ('lobbyServers', 'lobby_servers', ARRAY[]::text[]),
    ('lobbySetPosition', 'lobby_set_position', ARRAY['focus_since', 'seated', 'shard', 'subject', 'x', 'y']::text[]),
    ('lobbyLeave', 'lobby_leave', ARRAY[]::text[]),
    ('lobbyPeople', 'lobby_people', ARRAY['shard']::text[]),
    ('lobbyEmote', 'lobby_emote', ARRAY['kind']::text[]),
    ('libraryMessages', 'library_messages', ARRAY['shard', 'since']::text[]),
    ('sendLibraryMessage', 'send_library_message', ARRAY['body', 'shard']::text[]),
    ('reportLibraryMessage', 'report_library_message', ARRAY['block', 'message', 'reason']::text[])
),
have AS (
  SELECT p.proname AS fn, p.oid,
         (SELECT coalesce(array_agg(nm ORDER BY nm), ARRAY[]::text[])
            FROM (SELECT replace(split_part(trim(a), ' ', 1), '"', '') AS nm
                    FROM unnest(CASE WHEN pg_get_function_identity_arguments(p.oid) = '' THEN ARRAY[]::text[]
                                     ELSE string_to_array(pg_get_function_identity_arguments(p.oid), ', ') END) a) t) AS args
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public'
),
want_table(tbl, ladder) AS (VALUES
    ('social_profile', ARRAY['user_id,display_name,colour,friend_code,opted_in_at,avatar', 'user_id,display_name,colour,friend_code,opted_in_at', 'user_id,display_name,colour,avatar', 'user_id,display_name,colour']::text[]),
    ('friendship', ARRAY['user_id,friend_id,status,created_at']::text[]),
    ('study_group', ARRAY['id,name,invite_code,owner_id,created_at,emblem,hall_theme,weekly_goal_hours,visibility', 'id,name,invite_code,owner_id,created_at,emblem,hall_theme,weekly_goal_hours', 'id,name,invite_code,owner_id,created_at']::text[]),
    ('group_member', ARRAY['user_id,joined_at,role', 'group_id,user_id']::text[]),
    ('study_presence', ARRAY['user_id,subject_id,mode,phase,started_at,ends_at,expires_at']::text[]),
    ('social_summary', ARRAY['user_id,day,today_seconds,week_start,week_xp,level,updated_at,week_seconds,streak,streak_day', 'user_id,day,today_seconds,week_start,week_xp,level,updated_at,week_seconds', 'user_id,day,today_seconds,week_start,week_xp,level,updated_at']::text[]),
    ('group_message', ARRAY['id,group_id,sender,body,created_at,hidden']::text[]),
    ('group_reaction', ARRAY['id,group_id,user_id,to_user,kind,created_at,seen_at']::text[])
),
column_step AS (
  SELECT w.tbl,
         (SELECT min(i) FROM generate_subscripts(w.ladder, 1) i
           WHERE NOT EXISTS (SELECT 1 FROM unnest(string_to_array(w.ladder[i], ',')) c
                              WHERE NOT EXISTS (SELECT 1 FROM information_schema.columns k
                                                 WHERE k.table_schema = 'public' AND k.table_name = w.tbl AND k.column_name = c))) AS step,
         cardinality(w.ladder) AS steps
    FROM want_table w
)
SELECT area, what, CASE WHEN ok THEN 'ok' ELSE 'MISSING' END AS status, note FROM (
  SELECT 1 AS o, 'migration' AS area, m || ': ' || what AS what, ok, '' AS note FROM migrations
  UNION ALL
  SELECT 2, 'rpc', w.fn || '(' || array_to_string(w.args, ', ') || ')',
         EXISTS (SELECT 1 FROM have h WHERE h.fn = w.fn AND h.args = w.args AND has_function_privilege('authenticated', h.oid, 'EXECUTE') AND NOT has_function_privilege('anon', h.oid, 'EXECUTE')),
         CASE WHEN NOT EXISTS (SELECT 1 FROM have h WHERE h.fn = w.fn) THEN 'no such function'
              WHEN EXISTS (SELECT 1 FROM have h WHERE h.fn = w.fn AND has_function_privilege('anon', h.oid, 'EXECUTE')) THEN 'SIGNED-OUT VISITORS CAN CALL THIS' ELSE '' END
    FROM want_rpc w
  UNION ALL
  SELECT 3, 'table', w.tbl,
         to_regclass('public.' || w.tbl) IS NOT NULL
           AND coalesce((SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = to_regclass('public.' || w.tbl)), false)
           AND coalesce(has_table_privilege('authenticated', to_regclass('public.' || w.tbl), 'SELECT'), false)
           AND NOT coalesce(has_table_privilege('anon', to_regclass('public.' || w.tbl), 'SELECT'), false),
         CASE WHEN to_regclass('public.' || w.tbl) IS NULL THEN 'no such table'
              WHEN coalesce(has_table_privilege('anon', to_regclass('public.' || w.tbl), 'SELECT'), false) THEN 'SIGNED-OUT VISITORS CAN READ THIS' ELSE '' END
    FROM want_table w
  UNION ALL
  SELECT 4, 'columns', s.tbl, s.step IS NOT NULL,
         CASE WHEN s.step IS NULL THEN 'not even the oldest set' ELSE 'rung ' || s.step || ' of ' || s.steps END
    FROM column_step s
  UNION ALL
  SELECT 5, 'realtime', 'private channel policies on realtime.messages',
         to_regclass('realtime.messages') IS NOT NULL
           AND EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'realtime' AND tablename = 'messages' AND policyname IN ('plumi_realtime_receive', 'plumi_realtime_send')),
         CASE WHEN to_regclass('realtime.messages') IS NULL THEN 'Realtime is not on this project' ELSE '' END
) r
ORDER BY o, what;
